def run_lines(lab, rate, kb, mem_max, top=3113400, outcome="ok", hsh=GOOD, drop_k=None, launch=None,
              late=None, trace=None, cd_on=None, cd_lines=None, cd_reason=None):
    """One run: RESULT, WINDOW k=1..7 (k=1 at 5 blocks/s, k=2..7 at `rate`; windows 6-7 read `late` if given), a CACHEDROP line
    (default: F on=1 lines=1, N and W/V on=0 lines=0; `cd_on`, `cd_lines`, `cd_reason` override), and
    for W/V a TRACE line (`trace` overrides its fields)."""
    arm = lab.split("-")[1]
    secs = [200] + [round(1000 / rate) for _ in range(6)]
    launch = launch if launch is not None else 80 + sum(secs)
    out = ["RESULT label=%s top=%d blocks=7000 wall_s=%d outcome=%s launch_to_top_s=%d mem_max=%s cg_peak_MB=na hash_at_%d=%s" % (
        lab, top, sum(secs), outcome, launch, mem_max, top, hsh)]
    for k in range(1, 8):
        if k == drop_k:
            continue
        r = 3 if k == 1 else (late if late is not None and k in (6, 7) else kb)
        out.append("WINDOW label=%s k=%d from=%d to=%d secs=%d blocks_per_s=%.3f read_kB_per_block=%s write_kB_per_block=1200" % (
            lab, k, 3106400 + (k - 1) * 1000 + (1 if k == 1 else 0), 3106400 + k * 1000, secs[k - 1], 1000 / secs[k - 1], r))
    on = cd_on if cd_on is not None else (1 if arm == "F" else 0)
    n = cd_lines if cd_lines is not None else (1 if arm == "F" else 0)
    out.append("CACHEDROP label=%s arm=%s on=%d lines=%d reason=%s" % (lab, arm, on, n, cd_reason or "na"))
    if arm in "WV":
        t = {"pid": "4242", "bio_lines": "800000", "node_reads": "9000", "samples": "280", "fiemap_extents": "3", "partstart": "2048",
             "wlog": "W:1400000,F:1300000,D:800000,C:2100", "rc": "0", "dir": "/x/trace-%s" % lab}
        t.update(trace or {})
        out.append("TRACE label=%s " % lab + " ".join("%s=%s" % kv for kv in t.items()))
    return out


